DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[ProductSubcategory]([ProductSubcategoryID],[ProductCategoryID],[Name],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[ProductSubcategoryID],S.[ProductCategoryID],S.[Name],S.[rowguid],S.[ModifiedDate],@B FROM ssis_flow.Delta_ProductSubcategory S;
INSERT stg.[ProductSubcategory]([ProductSubcategoryID],[ProductCategoryID],[Name],[rowguid],[ModifiedDate],LoadBatchID) SELECT [ProductSubcategoryID],[ProductCategoryID],[Name],[rowguid],[ModifiedDate],@B FROM etl_raw.[ProductSubcategory];
INSERT etl_v2.SourceChange SELECT @B,N'Production.ProductSubcategory','I',@Next,(SELECT R.[ProductSubcategoryID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[ProductSubcategory] R;
END ELSE BEGIN
SELECT [ProductSubcategoryID],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_ProductSubcategory FROM ssis_flow.Delta_ProductSubcategory;
INSERT etl_v2.SourceChange SELECT @B,N'Production.ProductSubcategory',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[ProductSubcategoryID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_ProductSubcategory C LEFT JOIN etl_raw.[ProductSubcategory] R ON R.[ProductSubcategoryID]=C.[ProductSubcategoryID];
DELETE R FROM etl_raw.[ProductSubcategory] R JOIN #CT_ProductSubcategory C ON R.[ProductSubcategoryID]=C.[ProductSubcategoryID] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[ProductCategoryID]=S.[ProductCategoryID],R.[Name]=S.[Name],R.[rowguid]=S.[rowguid],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[ProductSubcategory] R JOIN #CT_ProductSubcategory C ON R.[ProductSubcategoryID]=C.[ProductSubcategoryID] JOIN ssis_flow.Delta_ProductSubcategory S ON S.[ProductSubcategoryID]=C.[ProductSubcategoryID] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[ProductSubcategory]([ProductSubcategoryID],[ProductCategoryID],[Name],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[ProductSubcategoryID],S.[ProductCategoryID],S.[Name],S.[rowguid],S.[ModifiedDate],@B FROM #CT_ProductSubcategory C JOIN ssis_flow.Delta_ProductSubcategory S ON S.[ProductSubcategoryID]=C.[ProductSubcategoryID] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[ProductSubcategory] R WHERE R.[ProductSubcategoryID]=S.[ProductSubcategoryID]);
INSERT stg.[ProductSubcategory]([ProductSubcategoryID],[ProductCategoryID],[Name],[rowguid],[ModifiedDate],LoadBatchID) SELECT R.[ProductSubcategoryID],R.[ProductCategoryID],R.[Name],R.[rowguid],R.[ModifiedDate],@B FROM etl_raw.[ProductSubcategory] R JOIN #CT_ProductSubcategory C ON R.[ProductSubcategoryID]=C.[ProductSubcategoryID] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;